## Your Personal Toolbox

Eight functions spanning every category you've learned. All called from `main()` in a formatted showcase.

### Math Tools

```xiom
fn factorial(n: Int) -> Int {
  if n < 0 {
    return 0;
  }
  var result = 1;
  var i = 1;
  while i <= n {
    result = result * i;
    i = i + 1;
  }
  return result;
}

fn sum_to(n: Int) -> Int {
  if n < 1 {
    return 0;
  }
  var total = 0;
  var i = 1;
  while i <= n {
    total = total + i;
    i = i + 1;
  }
  return total;
}
```

### String Tools

```xiom
fn reverse(text: Str) -> Str {
  let len = string.str_len(text);
  var result = "";
  var i = len - 1;
  while i >= 0 {
    result = string.str_concat(result, text[i]);
    i = i - 1;
  }
  return result;
}

fn count_vowels(text: Str) -> Int {
  let len = string.str_len(text);
  var count = 0;
  var i = 0;
  while i < len {
    let ch = text[i];
    if ch == 'a' or ch == 'e' or ch == 'i' or ch == 'o' or ch == 'u' {
      count = count + 1;
    }
    i = i + 1;
  }
  return count;
}
```

### Boolean Tools

```xiom
fn is_palindrome(text: Str) -> Bool {
  let len = string.str_len(text);
  var left = 0;
  var right = len - 1;
  while left < right {
    if text[left] != text[right] {
      return false;
    }
    left = left + 1;
    right = right - 1;
  }
  return true;
}

fn is_leap_year(year: Int) -> Bool {
  if year % 400 == 0 {
    return true;
  }
  if year % 100 == 0 {
    return false;
  }
  if year % 4 == 0 {
    return true;
  }
  return false;
}
```

### Random Tools

```xiom
fn roll_dice() -> Int {
  return math.random_range(1, 6);
}

fn random_fortune() -> Str {
  let fortunes = ["Good luck!", "Stay curious.", "Keep coding!", "You will succeed.", "Adventure awaits."];
  let idx = math.random_range(0, 4);
  return fortunes[idx];
}
```

